from autore import Modulo,estratto
from tikz_base import scrivi,n,a,rect,linea
m=Modulo('M15','Riproducibilità e progetto di analisi','Dati, funzioni, controlli numerici e storia delle decisioni')
def p(t,s,**kw):m.pagina(t,s,**kw)
def d(i,b):return scrivi('M15',i,b)
def flusso(i,labs):
 b=''
 for k,lab in enumerate(labs):
  y=.4+1.85*k;b+=rect(.5,y,6.9,y+1.15,'Classical' if k%2==0 else 'Quantum')+n(3.7,y+.575,lab,w=6,size=11.5)
  if k<len(labs)-1:b+=a(3.7,y+1.3,3.7,y+1.68)
 return d(i,b)
m.sezione_nuova('Dati e dipendenze dell’analisi')
p('Un risultato conserva la propria storia',
'''Una tabella conclusiva acquista significato quando è possibile ricostruire i dati dai quali deriva, le trasformazioni applicate e le decisioni che ne hanno delimitato il contenuto. Il capitolo riprende ventiquattro provini distribuiti in sei stazioni e sviluppa una procedura per calcolare densità e medie di stazione. La ripetibilità del calcolo viene verificata separatamente dalla validità dell’interpretazione geologica, che dipende dal disegno di campionamento, dalla misura del volume e dalla rappresentatività delle stazioni.''',tikz=flusso('D01',['Dati e protocollo di misura','Trasformazioni e controlli','Risultato con provenienza']),richiamo='La riproduzione del calcolo richiede una storia verificabile dei dati e delle scelte.',origine='M15:1–10')
p('Separazione fra sorgenti e prodotti derivati',
'''I dati ricevuti vengono conservati in una cartella dedicata, mentre tabelle derivate, figure e registri di esecuzione sono scritti in destinazioni distinte. Questa organizzazione consente di ricostruire le trasformazioni e di confrontare una nuova elaborazione con la precedente. Una correzione del dato sorgente deve produrre una versione riconoscibile e una motivazione, affinché la differenza fra misura originaria e dato corretto rimanga documentata. La struttura delle cartelle esprime dunque una relazione di dipendenza fra oggetti scientifici.''',tikz=d('D02',rect(.4,2.1,2.6,3.6)+n(1.5,2.85,'dati/',w=1.9)+a(2.8,2.85,4.1,1.3)+a(2.8,2.85,4.1,4.5)+rect(4.3,.6,7,2,'Quantum')+n(5.65,1.3,'tabelle/',w=2.4)+rect(4.3,3.8,7,5.2)+n(5.65,4.5,'figure/',w=2.4)+n(3.7,5.9,'Gli script dichiarano le dipendenze.',w=6.7,size=11)),richiamo='Ogni prodotto derivato deve poter essere ricostruito senza sovrascrivere l’input.',origine='M15:11–15')
p('Il dizionario collega colonne e misure',
'''Il nome di una variabile permette di individuarla nel codice, mentre la sua interpretazione richiede unità, supporto della misura, metodo e convenzioni per i valori mancanti. Nel caso didattico, massa_g e volume_cm3 consentono una densità in grammi per centimetro cubo; l’identificativo distingue i provini e la stazione conserva il livello geografico del campionamento. Un controllo automatico può verificare la presenza delle colonne e l’unicità degli identificativi, mentre la pertinenza delle definizioni richiede conoscenza del protocollo.''',formula=r'\rho_i=\frac{m_i}{V_i},\qquad [\rho]=\mathrm{g\,cm^{-3}}',destra='Il dizionario associa a ogni colonna un significato, un’unità e un ruolo. Per gli identificativi si conserva il formato testuale; per le categorie si registrano i livelli ammessi; per le misure si dichiarano precisione, intervallo plausibile e codici di assenza.',richiamo='Il controllo dello schema deve essere accompagnato dalla verifica del significato delle variabili.',origine='M15:16–20')
c=estratto('M15','percorsi',"f <- file.path('dati','campioni_modulo1.csv')\nstopifnot(file.exists(f))\nd <- read.csv(f,stringsAsFactors=FALSE)\nstopifnot(nrow(d)==24,\n !anyDuplicated(d$id),\n all(c('massa_g','volume_cm3') %in% names(d)))\nhead(d)")
p('Radice del progetto e percorsi relativi',
'''Un percorso relativo viene interpretato rispetto alla cartella corrente, che può variare fra terminale, ambiente di sviluppo e documento eseguibile. La procedura del corso assume come radice la cartella contenente dati, R e sorgenti, dalla quale si avviano gli script. file.path compone i segmenti senza incorporare il percorso personale del docente. La verifica iniziale dell’esistenza del file permette di distinguere un errore di avvio da un problema di lettura o di contenuto della tabella.''',codice=c,richiamo='La cartella di avvio fa parte delle istruzioni necessarie a riprodurre un’analisi.',origine='M15:31–35')
m.sezione_nuova('Identità e confronto numerico')
p('Impronta dei byte ed equivalenza dei valori',
'''Un’impronta permette di confrontare un file con un riferimento prestabilito. Una differenza rileva una modifica della rappresentazione, che può riguardare anche soltanto un separatore o il numero di cifre stampate. Due CSV contenenti rispettivamente 1 e 1.0 possono quindi produrre impronte differenti e restituire lo stesso valore numerico dopo la lettura. Il manifest della consegna utilizza SHA-256; il laboratorio presenta anche MD5 come esempio di checksum, senza attribuirgli una funzione di sicurezza crittografica.''',tikz=d('D03',rect(.4,.6,3.4,2.1)+n(1.9,1.35,'A,1',w=2.6,size=16)+rect(4,.6,7,2.1,'Quantum')+n(5.5,1.35,'A,1.0',w=2.6,size=16)+a(1.9,2.3,1.9,3.2)+a(5.5,2.3,5.5,3.2,'Quantum')+n(1.9,3.8,'Byte differenti',w=2.8)+n(5.5,3.8,'Valore uguale',w=2.8)+n(3.7,5.3,'Due criteri di confronto rispondono a domande diverse.',w=6.7,size=11.5)),richiamo='L’integrità del file e l’equivalenza scientifica del contenuto richiedono controlli distinti.',origine='M15:21–25,101–105')
p('Tolleranza assoluta e tolleranza relativa',
'''Il confronto fra quantità numeriche richiede una soglia coerente con la loro scala e con l’errore computazionale atteso. Una componente assoluta protegge il confronto vicino allo zero, mentre una componente relativa cresce con il valore di riferimento. Le tolleranze di calcolo devono essere distinte dall’incertezza di misura: scegliere una soglia piccola verifica l’implementazione, senza rendere più preciso lo strumento. Nell’esempio si controlla la densità dopo esportazione e lettura, mantenendo invariati identificativi e ordine dei provini.''',formula=r'|x-y|\leq\varepsilon_{\rm abs}+\varepsilon_{\rm rel}|x|',destra='La regola usa x come riferimento ed è quindi asimmetrica. Un criterio simmetrico può sostituire |x| con max(|x|, |y|), purché la scelta sia dichiarata. In R, all.equal restituisce TRUE oppure una descrizione delle differenze; un controllo logico richiede isTRUE(all.equal(...)).',richiamo='La tolleranza numerica deve essere definita rispetto all’operazione e alla scala dei valori.',fonti='R: all.equal',origine='M15:26–30,66–70')
c=estratto('M15','roundtrip',"d <- read.csv('dati/campioni_modulo1.csv')\nd$densita <- d$massa_g/d$volume_cm3\nf <- tempfile(fileext='.csv')\nwrite.csv(d,f,row.names=FALSE,na='NA')\nq <- read.csv(f,na.strings='NA')\nstopifnot(identical(q$id,d$id))\ne <- abs(q$densita-d$densita)\nstopifnot(all(e <= 1e-12+\n 1e-10*abs(d$densita)))\nunlink(f)")
p('Esportazione e rilettura come prova integrata',
'''La prova di andata e ritorno coinvolge scrittura, formato del file, interpretazione delle colonne e recupero dei valori. Il controllo degli identificativi impedisce che una tabella numericamente plausibile nasconda un riordinamento o la perdita di righe. Per le densità si applica una tolleranza esplicita, mentre i codici di assenza vengono dichiarati in entrambe le direzioni. Il file temporaneo consente di eseguire la verifica senza introdurre un nuovo input nella cartella dei dati sorgente.''',codice=c,richiamo='Una prova di esportazione verifica insieme contenuto, identità delle righe e convenzioni di lettura.',origine='M15:26–30')
p('Arrotondamento e perdita di informazione',
'''Arrotondare i risultati prima di completarli introduce un errore che può propagarsi nelle operazioni successive. La figura confronta l’errore massimo sulle densità conservando zero, una o due cifre decimali. Nel dataset didattico le densità sono state costruite con due decimali, per cui questa precisione recupera i valori entro l’approssimazione numerica. Il caso distingue la formattazione destinata alla lettura dalla precisione conservata nel calcolo: una tabella può mostrare poche cifre lasciando disponibili valori più precisi nel file di lavoro.''',figura='M15/F03',didascalia='Errore assoluto massimo rispetto alle densità calcolate. Il valore a due decimali è nullo entro la precisione macchina.',richiamo='La precisione di stampa deve essere scelta dopo le trasformazioni che utilizzano i valori.',origine='M15:26–30,66–70; approfondimento R5')
p('Zero, assenza e convenzione di scambio',
'''Uno zero rappresenta un valore, mentre NA indica che il valore non è disponibile secondo la convenzione adottata. Un campo vuoto può assumere significati diversi nei programmi che leggono il file, per cui il formato di scambio deve specificare il codice utilizzato. La scelta di escludere i mancanti da una sintesi modifica l’insieme delle osservazioni considerate e richiede una motivazione rispetto al processo che ha prodotto l’assenza. La conservazione del codice durante l’esportazione precede tale decisione analitica.''',tikz=d('D04',rect(.6,.8,2.7,2.6)+n(1.65,1.7,'0',size=24)+rect(4.7,.8,6.8,2.6,'Quantum')+n(5.75,1.7,'NA',size=22)+n(1.65,3.6,'Valore misurato',w=2.8)+n(5.75,3.6,'Valore assente',w=2.8)+n(3.7,5.3,'Il codice di assenza si conserva nello scambio.',w=6.5,size=11.5)),richiamo='Il trattamento dei mancanti è una decisione scientifica successiva al riconoscimento del loro codice.',origine='M15:51–55')
m.sezione_nuova('Funzioni e contratti di validità')
c=estratto('M15','validazione',"densita <- function(m,v) {\n stopifnot(is.numeric(m),is.numeric(v),\n  length(m)==length(v),length(m)>0,\n  all(is.finite(m)),all(is.finite(v)),\n  all(m>0),all(v>0))\n m/v\n}\nstopifnot(densita(10,4)==2.5)\nerrore <- tryCatch({densita(10,0);FALSE},\n error=function(e)TRUE)\nstopifnot(errore)")
p('Una funzione dichiara il proprio dominio',
'''La funzione di densità richiede masse e volumi numerici, finiti, positivi e della stessa lunghezza. Il controllo delle lunghezze evita il riciclo implicito dei vettori, che potrebbe associare masse e volumi in modo diverso da quello previsto. Un volume nullo viene intercettato prima della divisione e produce un errore riconoscibile. Il contratto descrive le condizioni necessarie al calcolo, mentre la plausibilità dei valori e la corrispondenza fra provino e misura richiedono ulteriori controlli del protocollo.''',formula=r'f:\{(m,V):m>0,\ V>0\}\longrightarrow\mathbb R_{>0}',codice=c,richiamo='I controlli dell’input traducono in condizioni eseguibili il dominio dichiarato della funzione.',origine='M15:56–60')
p('Composizione delle trasformazioni',
'''Una procedura può essere scomposta in lettura, validazione, trasformazione e sintesi. Ogni passaggio produce un oggetto il cui contenuto può essere controllato prima di procedere, riducendo la difficoltà di localizzare un errore. Nel caso della densità, la trasformazione aggiunge una colonna a una copia della tabella, mentre la sintesi raggruppa i provini per stazione. La funzione restituisce il risultato senza modificare l’input e senza dipendere da variabili nascoste nella sessione di lavoro.''',formula=r'Y=(S\circ T\circ V)(D)',tikz=flusso('D05',['V: verifica del dominio','T: densità di ogni provino','S: sintesi per stazione']),richiamo='La scomposizione espone gli oggetti intermedi sui quali verificare il procedimento.',origine='M15:61–65,106–110')
p('Ripetibilità e idempotenza sono proprietà diverse',
'''Una funzione deterministica restituisce lo stesso risultato quando riceve gli stessi input e opera nello stesso ambiente. L’idempotenza richiede invece che applicare nuovamente la funzione al suo risultato lasci quest’ultimo invariato. Il raddoppio di un numero è deterministico, pur modificando ancora il valore se viene ripetuto sull’uscita. La distinzione permette di formulare prove appropriate: il confronto fra due esecuzioni della procedura parte entrambe le volte dalla medesima tabella sorgente.''',formula=r'f(D)=f(D)\quad\text{a parità di condizioni}\\f(f(D))=f(D)\quad\text{solo per funzioni idempotenti}',destra='Per f(x) = 2x, due chiamate con x = 3 restituiscono entrambe 6, mentre f(f(3)) vale 12. Un filtro che conserva soltanto volumi positivi è invece idempotente, purché la stessa regola venga applicata a un oggetto compatibile.',richiamo='La proprietà da verificare deve essere formulata prima di scrivere il confronto.',origine='M15:61–65; approfondimento R5')
p('Esempi manuali, casi limite e invarianti',
'''Un valore calcolabile a mano offre un riferimento indipendente per verificare la formula, mentre i casi limite mettono alla prova il dominio della funzione. Gli invarianti esprimono proprietà che devono restare vere durante una trasformazione, come la conservazione degli identificativi dopo l’aggiunta della densità. La riuscita di queste prove aumenta la fiducia nell’implementazione entro i casi esaminati; la copertura va estesa quando emergono nuovi errori o nuove condizioni d’uso, evitando confronti che ripetano semplicemente lo stesso codice da verificare.''',tikz=d('D06',rect(.6,.5,6.8,1.7)+n(3.7,1.1,r'Valore noto: $10/4=2{,}5$',w=5.9)+rect(.6,2.4,6.8,3.6,'Quantum')+n(3.7,3,'Caso limite: volume nullo',w=5.9)+rect(.6,4.3,6.8,5.5,'Measure')+n(3.7,4.9,'Invariante: stessi identificativi',w=5.9)),richiamo='Le prove più utili confrontano l’implementazione con un riferimento indipendente o una proprietà sostanziale.',origine='M15:66–70')
p('Densità dei provini e sintesi delle stazioni',
'''La figura conserva le ventiquattro osservazioni individuali e sovrappone le sei medie di stazione, rendendo visibili sia la variabilità interna sia le differenze fra gruppi. I punti sono leggermente separati in orizzontale per facilitarne la lettura, senza alterare i valori verticali. La sintesi costituisce l’uscita della procedura deterministica, mentre un’inferenza sulle differenze fra affioramenti richiederebbe di rispettare la struttura gerarchica del campionamento. La disponibilità di quattro provini per stazione non moltiplica automaticamente le repliche geografiche.''',formula=r'\overline\rho_s=\frac1{n_s}\sum_{i\in s}\rho_i',figura='M15/F01',didascalia='Punti verdi: provini. Rombi viola: medie delle sei stazioni, con quattro provini ciascuna.',richiamo='La sintesi conserva il livello geografico al quale appartengono le osservazioni.',origine='M15:106–110')
m.sezione_nuova('Casualità e ambiente di esecuzione')
p('Il seme identifica una sequenza in un ambiente',
'''La generazione pseudocasuale evolve uno stato interno secondo un algoritmo deterministico. Il seme inizializza tale stato, mentre algoritmo, versione e ordine delle chiamate determinano la sequenza successiva. Due programmi in linguaggi diversi possono utilizzare generatori o trasformazioni differenti, pur ricevendo lo stesso numero come seme. Anche nello stesso linguaggio, l’aggiunta di un’estrazione prima del bootstrap modifica tutte le estrazioni successive. Per riprodurre un confronto si registrano quindi generatore, ambiente e procedimento, oltre al seme.''',formula=r's_{k+1}=G(s_k),\qquad u_k=H(s_k)',tikz=flusso('D07',['Seme e algoritmo dichiarati','Stato e ordine delle chiamate','Sequenza utilizzata nell’analisi']),richiamo='La sequenza dipende dall’intero procedimento di generazione.',fonti='R: Random Number Generation',origine='M15:41–45')
c=estratto('M15','indici',"d <- read.csv('dati/campioni_modulo1.csv')\nu <- read.csv('dati/casuali_comuni_v3.csv')$u\nix <- matrix(floor(24*u[1:240])+1,\n nrow=10,byrow=TRUE)\nrho <- d$massa_g/d$volume_cm3\nb <- apply(ix,1,function(i)mean(rho[i]))\nstopifnot(all(ix>=1 & ix<=24))\ndata.frame(replica=1:10,media=b)")
p('Un piano di ricampionamento condiviso',
'''Per confrontare implementazioni si possono conservare le estrazioni uniformi e trasformarle negli stessi indici di riga. Nel laboratorio, le prime 240 uniformi producono dieci campioni di ventiquattro provini con reinserimento. R usa indici che iniziano da uno, mentre Python parte da zero; l’aggiunta di uno modifica la convenzione dell’indice, mantenendo identica la riga selezionata. Il confronto richiede che coincidano anche ordine dei dati, regola di trasformazione e disposizione delle estrazioni nella matrice.''',formula=r'i_R=1+\lfloor nu\rfloor,\qquad i_{Python}=\lfloor nu\rfloor,\quad 0\leq u<1',codice=c,richiamo='Un piano casuale condiviso rende confrontabili procedure che usano generatori diversi.',origine='M15:46–50')
p('Verifica delle medie ricampionate',
'''Le dieci medie derivano dal medesimo piano casuale e vengono conservate come tabella di confronto fra implementazioni. La linea tratteggiata indica la media dei ventiquattro provini, rispetto alla quale le repliche oscillano perché cambiano le molteplicità delle osservazioni selezionate. Dieci ripetizioni sono sufficienti per questo controllo di corrispondenza e restano inadeguate per una stima accurata dei quantili di coda. Un uso inferenziale richiederebbe inoltre di valutare se ricampionare provini o stazioni rispetto alla domanda scientifica.''',figura='M15/F02',didascalia='Dieci medie ottenute dalle uniformi archiviate. Il controllo tra linguaggi usa le stesse righe nello stesso ordine.',richiamo='Il confronto fra implementazioni e la stima dell’incertezza hanno requisiti differenti.',origine='M15:46–50')
p('Documentare l’ambiente e ricostruirlo',
'''sessionInfo registra versione di R, piattaforma e pacchetti caricati, fornendo il contesto nel quale il risultato è stato ottenuto. La ricostruzione dell’ambiente richiede anche la disponibilità delle dipendenze e delle librerie di sistema, che possono variare fra piattaforme. Un elenco di versioni costituisce una testimonianza dell’esecuzione; un file di dipendenze risolte o un ambiente isolato ne facilita il ripristino. Il collaudo deve infine partire da una sessione pulita, affinché oggetti creati in precedenza non sostituiscano dipendenze mancanti.''',destra='La consegna conserva codice, dati utilizzati, versioni rilevate e registri di esecuzione. I risultati numerici vengono confrontati con tolleranze appropriate. Differenze di dispositivo grafico o libreria dei caratteri possono modificare la resa visiva pur lasciando invariati i valori sottostanti.',richiamo='La documentazione dell’ambiente deve accompagnare una prova di esecuzione da condizioni iniziali dichiarate.',origine='M15:36–40')
m.sezione_nuova('Parametri, versioni e provenienza')
p('Una soglia modifica il campione analizzato',
'''La soglia sul volume viene registrata in un file di parametri e applicata con una disuguaglianza esplicita. Aumentandola, il numero dei provini conservati può soltanto diminuire o restare invariato, poiché gli insiemi selezionati sono annidati. Questa proprietà fornisce un controllo del codice. Il valore della soglia richiede invece una motivazione legata al protocollo di misura, alla qualità del provino o alla domanda di ricerca; la sua visibilità nel file rende la decisione ispezionabile senza giustificarla automaticamente.''',formula=r'A(c)=\{i:V_i\geq c\},\qquad c_2>c_1\Rightarrow A(c_2)\subseteq A(c_1)',figura='M15/F04',didascalia='Numero di provini conservati per sei soglie prefissate. Le quantità sono ricalcolate sui dati del laboratorio.',richiamo='Una proprietà matematica del filtro aiuta a verificare l’implementazione, mentre la soglia richiede una motivazione.',origine='M15:71–75')
p('Sensibilità della sintesi al criterio di selezione',
'''La media delle densità cambia quando il filtro elimina provini con caratteristiche diverse da quelle conservate. La curva permette di esaminare tale dipendenza per le stesse soglie della pagina precedente. Un tratto stabile riguarda soltanto i valori e i criteri considerati, mentre un cambiamento marcato suggerisce di esaminare quali stazioni e quali provini siano stati esclusi. Il confronto va accompagnato dai conteggi, poiché una media calcolata su pochi campioni può apparire simile alla media complessiva pur avendo un supporto osservativo molto diverso.''',figura='M15/F05',didascalia='Media delle densità dopo ciascun filtro sul volume. A 55 cm³ nessun provino resta disponibile e la media è indefinita.',richiamo='La sensibilità di una sintesi deve essere letta insieme alla composizione del campione che la sostiene.',origine='M15:71–80; approfondimento R5')
p('Registrare la decisione e le osservazioni coinvolte',
'''Il registro delle decisioni associa a ogni trasformazione una regola, una motivazione, il momento della scelta e gli identificativi interessati. I conteggi prima e dopo il filtro permettono di controllare l’effetto complessivo, mentre l’elenco dei provini esclusi consente di verificare eventuali concentrazioni per stazione. La data di esecuzione documenta l’elaborazione e deve rimanere distinta dalla data di campionamento. Se una soglia viene modificata dopo aver osservato i risultati, anche questa circostanza entra nella descrizione del procedimento.''',tikz=flusso('D08',['Regola, unità e motivazione','Identificativi e conteggi prima/dopo','Effetto sulla conclusione']),richiamo='Il registro rende ricostruibile il rapporto fra scelta analitica e risultato.',origine='M15:76–80')
p('Commit e differenze nel codice',
'''Un sistema di versionamento conserva stati riconoscibili dei file e permette di confrontare le modifiche. Prima di registrare un commit si esamina il diff, collegando le righe cambiate alla motivazione scientifica e agli effetti attesi. Il laboratorio crea un repository locale e modifica una soglia dimostrativa, senza richiedere un servizio remoto. La cronologia del codice permette di ricostruire il cambiamento, mentre il messaggio e il registro delle decisioni ne esplicitano il significato per l’analisi.''',tikz=d('D09',rect(.5,.8,3.2,2.8)+n(1.85,1.8,r'Versione A\par soglia = 4',w=2.4)+rect(4.2,.8,6.9,2.8,'Quantum')+n(5.55,1.8,r'Versione B\par soglia = 5',w=2.4)+a(3.4,1.8,4,1.8)+n(3.7,4,'Diff: modifica osservabile',w=6)+n(3.7,5.3,'Commit: stato e motivazione del cambiamento',w=6.6,size=11.5)),richiamo='La storia delle modifiche acquista valore quando è collegata alle ragioni e alle conseguenze delle decisioni.',origine='M15:81–90')
p('File locali e regole di esclusione',
'''La regola gitignore controlla l’inclusione ordinaria dei file ancora non tracciati, consentendo di separare prodotti rigenerabili, configurazioni locali e sorgenti condivisi. Un file già registrato mantiene la propria storia anche quando viene aggiunto a una regola di esclusione. Nel laboratorio si utilizza un segnaposto privo di credenziali reali per osservare il comportamento del comando check-ignore. Il contenuto effettivamente incluso in una consegna deve essere verificato nell’archivio finale, poiché le regole del repository e la selezione dei file distribuiti possono differire.''',destra='Le figure definitive possono essere distribuite insieme al codice che le produce, mentre file temporanei e risultati intermedi rigenerabili possono essere esclusi. La scelta dipende dalla funzione del pacchetto: esecuzione, revisione scientifica oppure consultazione didattica.',richiamo='Le regole di esclusione devono essere verificate rispetto ai file effettivamente tracciati e distribuiti.',fonti='Git: gitignore',origine='M15:91–95')
p('Risposte di servizi e copie locali verificabili',
'''Una risposta acquisita da un servizio può cambiare quando variano dati, parametri o versione dell’interfaccia. Conservare la risposta grezza insieme a indirizzo, parametri pubblici, data di accesso, unità e condizioni d’uso rende possibile una successiva verifica. Il laboratorio usa un JSON costruito localmente, nel quale due osservazioni hanno identificativi e valori in metri. La natura dimostrativa del file rimane esplicita: il controllo dello schema esercita la lettura di una risposta senza attribuirle una provenienza osservativa reale.''',tikz=flusso('D10',['Richiesta e metadati di accesso','Risposta grezza conservata','Schema verificato e tabella derivata']),richiamo='La provenienza di una risposta deve essere conservata prima della sua trasformazione in tabella.',origine='M15:96–100')
p('Manifest e consegna riproducibile',
'''Il manifest elenca i file distribuiti con dimensione e impronta, permettendo di riconoscere assenze e modifiche rispetto alla versione consegnata. Il lettore deve inoltre disporre di istruzioni per avviare gli script, informazioni sull’ambiente e una descrizione dei risultati attesi. I laboratori N01–N06 sviluppano struttura e integrità; N07–N12 casualità e prove; N13–N19 parametri, versioni e provenienza; N20 riunisce i passaggi nella sintesi per stazione. L’esercizio conclusivo richiede una nuova esecuzione da una sessione pulita e il confronto dei risultati.''',destra='La relazione finale distingue l’identità dei file, l’equivalenza numerica dei risultati e la validità scientifica della procedura. Per ciascun livello indica il controllo eseguito, il riferimento utilizzato e le condizioni entro le quali il confronto è pertinente.',richiamo='La consegna deve consentire sia l’esecuzione sia l’esame critico delle scelte scientifiche.',origine='M15:101–110')
